mapper.select:
SELECT a.`id` as task_id, a.`plan_id`, a.`plan_name`, a.`plan_task_id`, DATE_FORMAT( a.`plan_time`, '%Y-%m-%d %H:%i' ) as plan_time_t, DATE_FORMAT( a.`reality_time`, '%Y-%m-%d %H:%i' ) as reality_time, a.`task_status`, a.`create_time`, a.`create_user`, a.`update_time`, a.`update_user`, a.`delete_flag`, a.`medium_status`, a.`tenant_id`, a.`industry_code`, a.`access_node`, a.`accept_node`, a.`is_it_enabled`,a.fly_time,a.error_reason,a.break_point_json,a.task_type,a.uav_code, a.frog_leap,i.device_name as startNestName,e.device_name as endNestName,d.device_name as deviceName, a.start_nest_code as uavNestCode FROM vm_air_task_t a left join vm_air_plan_t ap on ap.plan_id = a.plan_id LEFT JOIN vm_uav_nest_device_info i on a.start_nest_code = i.device_code COLLATE utf8mb4_general_ci LEFT JOIN vm_uav_nest_device_info e on a.end_nest_code = e.device_code COLLATE utf8mb4_general_ci LEFT JOIN vm_uav_device_info_t d on a.uav_code = d.device_code COLLATE utf8mb4_general_ci where a.plan_id in
#{item}
and a.delete_flag = 0
and a.task_type in
#{item}
and DATE_FORMAT(a.reality_time,'%Y-%m-%d %H:%i:%s') >= #{realityStartTime} and DATE_FORMAT(a.reality_time,'%Y-%m-%d %H:%i:%s') <= #{realityEndTime}

select a.id, a.plan_id, a.plan_name, a.flight_route_id, a.`status`, a.plan_type, a.device_code, a.plan_time as plan_time_a,
a.uav_nest_code,a.auto_resume,
a.plan_end_time, a.plan_start_time, a.regular_execution_date, a.cycle_execution_unit, a.day_interval,
a.interval_values, a.gain_video, a.auto, a.gain_data_mode, a.tenant_id, a.industry_code,a.app_ver_code, a.create_time,
a.create_user, a.update_time, a.update_user, a.delete_flag, a.access_node, a.accept_node,a.uav_code,a.is_it_enabled,a.cycle_execution_time,
(case when length(IFNULL(rel.device_name, '')) = 0 then d.device_name else rel.device_name end ) as device_name,
l.flight_route_name,
l.extra_field,l.type,
(CASE WHEN length(IFNULL(relnest.device_name, '')) = 0 THEN i.device_name ELSE relnest.device_name END) AS uav_nest_name,
l.uav_allowed,a.snapshot_id,a.video_definition as definition,
i.device_name as startNestName,
ii.device_name as endNestName,
l.frog_leap as frogLeap
FROM vm_air_plan_t a
LEFT JOIN vm_air_line_t l on a.flight_route_id = l.flight_route_id
LEFT JOIN vm_uav_device_info_t d ON l.device_code = d.uav_nest_code
LEFT JOIN vm_uav_nest_device_info i on l.start_nest_code = i.device_code
LEFT JOIN vm_uav_nest_device_info ii on l.end_nest_code = ii.device_code
LEFT JOIN vm_tenant_device_common_rel_t relnest ON relnest.device_code = i.device_code
and relnest.tenant_id = #{tenantId}
and relnest.industry_code = #{industryCode}
and relnest.delete_flag = '0'
and relnest.device_type = 4
LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = d.device_code
and rel.tenant_id = #{tenantId}
and rel.industry_code = #{industryCode}
and rel.delete_flag = '0'
and rel.device_type = 1


        and (a.plan_name like CONCAT('%', #{planName}, '%')
        OR EXISTS (SELECT 1 FROM vm_air_task_t t LEFT JOIN vm_air_plan_t ap ON ap.plan_id = t.plan_id WHERE t.plan_name LIKE CONCAT('%', #{planName}, '%') AND ap.plan_id = a.plan_id AND t.delete_flag = 0))



            and EXISTS (SELECT 1 FROM vm_air_task_t WHERE plan_id = a.plan_id and ((task_status IN

                #{item}

            ) or is_it_enabled = 1) )




            and EXISTS (SELECT 1 FROM vm_air_task_t WHERE plan_id = a.plan_id and task_status IN

                #{item}

            )



        and a.plan_type IN

            #{item}



        and a.plan_time >= #{planStartTime}


        and a.plan_time <= #{planEndTime}


        and l.flight_route_id = #{flightRouteId}


        and l.flight_route_name like CONCAT('%', #{flightRouteName}, '%')


        AND (
        CASE WHEN LENGTH(IFNULL(rel.device_name, '')) = 0
        THEN d.device_name
        ELSE rel.device_name
        END
        ) LIKE CONCAT('%', #{deviceName}, '%')


        AND (
        CASE WHEN LENGTH(IFNULL(relnest.device_name, '')) = 0
        THEN i.device_name
        ELSE relnest.device_name
        END
        ) LIKE CONCAT('%', #{uavNestName}, '%')


        and a.device_Code = #{deviceCode}


        and a.plan_id IN (
        SELECT
        plan_id
        FROM
        vm_air_task_t
        WHERE
        task_type in

             #{item}

        and tenant_id = #{tenantId}
        and industry_code = #{industryCode}
        )


        and a.plan_id IN (
        SELECT
        plan_id
        FROM
        vm_air_task_t
        WHERE
        DATE_FORMAT(reality_time,'%Y-%m-%d %H:%i:%s') >= #{realityStartTime}
        and
        DATE_FORMAT(reality_time,'%Y-%m-%d %H:%i:%s') <= #{realityEndTime}
        and tenant_id = #{tenantId}
        and industry_code = #{industryCode}
        )

    and a.delete_flag = 0
    and l.device_code in (select device_code from vm_order_uav_nest_devices where tenant_id = a.tenant_id and industry_code = a.industry_code and ord_status in (0,1,2))

        and a.auto_resume = #{autoResume}


        and l.frog_leap = #{frogLeap}


        and i.device_name LIKE CONCAT('%', #{startNestName}, '%')


        and ii.device_name LIKE CONCAT('%', #{endNestName}, '%')


${dataScope}
ORDER BY a.create_time desc

SELECT plan_id, reality_time FROM ( SELECT b.plan_id, a.reality_time, ROW_NUMBER() OVER (PARTITION BY b.plan_id ORDER BY a.reality_time DESC) AS rn FROM vm_air_task_t a LEFT JOIN vm_air_plan_t b ON a.plan_id = b.plan_id WHERE a.task_status IN ('1', '3')
and b.plan_id in
#{item}
) t WHERE rn = 1 ORDER BY reality_time DESC

select a.id, a.plan_id, a.plan_name, a.flight_route_id, a.`status`, a.plan_type, a.device_code, a.plan_time as plan_time_a, a.uav_nest_code, a.plan_end_time, a.plan_start_time, a.regular_execution_date, a.cycle_execution_unit, a.day_interval, a.interval_values, a.gain_video, a.auto, a.gain_data_mode, a.tenant_id, a.industry_code, a.app_ver_code, a.create_time, a.create_user, a.update_time, a.update_user, a.delete_flag, a.access_node, a.accept_node,a.uav_code,d.device_name,l.flight_route_name, l.extra_field,l.type,i.device_name as uav_nest_name i.device_name as startNestName, ii.device_name as endNestName FROM vm_air_plan_t a LEFT JOIN vm_uav_device_info_t d ON a.uav_code = d.device_code LEFT JOIN vm_uav_nest_device_info i on l.start_nest_code = i.device_code LEFT JOIN vm_uav_nest_device_info ii on l.end_nest_code = ii.device_code LEFT JOIN vm_air_line_t l on a.flight_route_id = l.flight_route_id
a.plan_name like CONCAT('%', #{planName}, '%')
and a.`status` IN
#{item}
and a.plan_type IN
#{item}
and a.plan_time >= #{planStartTime}
and a.plan_time <= #{planEndTime}
and l.flight_route_name like CONCAT('%', #{flightRouteName}, '%')
and d.device_name like CONCAT('%', #{deviceName}, '%')
and a.uav_nest_code like CONCAT('%', #{uavNestCode}, '%')
and a.delete_flag = 0
ORDER BY a.create_time desc

SELECT
    CONCAT('新建计划', COUNT(*) + 1) AS new_plan_name
FROM
    vm_air_plan_t
WHERE
    tenant_id = #{tenantId}
  AND industry_code = #{industryCode}
  AND delete_flag = 0;

select id,plan_name,tenant_id,industry_code
from vm_air_plan_t
where tenant_id = #{tenantId}
  and industry_code = #{industryCode}
  and plan_name = #{planName}
  and delete_flag = 0
limit 1;

SELECT COUNT(1)
FROM vm_air_plan_t
WHERE
  flight_route_id = #{flightRouteId}
  AND tenant_id = #{tenantId}
  AND industry_code = #{industryCode}
  AND delete_flag = 0
  and

        plan_time between concat(#{planTime}, ' ', '00:00:00') and concat(#{planTime}, ' ', '23:59:59')

SELECT COUNT(DISTINCT DATE(t.plan_time))
FROM vm_air_task_t t
INNER JOIN vm_air_plan_t p ON p.plan_id = t.plan_id
WHERE
    p.flight_route_id = #{flightRouteId}
  AND p.tenant_id = #{tenantId}
  AND p.industry_code = #{industryCode}
  AND p.delete_flag = 0
  AND t.delete_flag = 0
  AND DATE(t.plan_time) in

        #{planTime}

SELECT
    MAX( REPLACE ( plan_name, CONCAT( #{planName}, '_复制' ), '' ) + 1 )
FROM
    vm_air_plan_t
WHERE
    tenant_id = #{tenantId}
AND industry_code = #{industryCode}
AND
    plan_name LIKE CONCAT( #{planName}, '%' )
  AND TRUNCATE ((
                    CHAR_LENGTH(
                            REPLACE ( plan_name, #{planName}, '' )) - CHAR_LENGTH(
                            REPLACE ( REPLACE ( plan_name, #{planName}, '' ), '_复制', '' ))
                    )/ CHAR_LENGTH( '_复制' ),
                0
      ) = 1;
